interface Box<T> {
  value: T;
}

interface ApiResponse<T> {
  ok: boolean;
  data: T;
}

class Stack<T> {
  private items: T[] = [];

  push(item: T): void {
    this.items.push(item);
  }

  pop(): T | undefined {
    return this.items.pop();
  }
}

const numBox: Box<number> = { value: 7 };
const res: ApiResponse<string[]> = { ok: true, data: ["a", "b"] };

const stack = new Stack<string>();
stack.push("one");
stack.push("two");

console.log(numBox.value, res.data.length);
console.log(stack.pop(), stack.pop(), stack.pop());

